local OverseaManegeMenuRecommendPopupCell = Class('OverseaManegeMenuRecommendPopupCell')
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")

function OverseaManegeMenuRecommendPopupCell:__init()
    self.skillId = nil
end

function OverseaManegeMenuRecommendPopupCell:__delete()
    self.skillId = nil
end

function OverseaManegeMenuRecommendPopupCell:Awake()
    self:AddUIClick()
end

function OverseaManegeMenuRecommendPopupCell:AddUIClick()
    SetButtonAction(self.BtnExplain,Bind(self,self.OnBtnExplainClick))
    SetButtonAction(self.GoToGet,Bind(self,self.OnBtnGoToGetClick))
    SetButtonAction(self.BtnGoToGet,Bind(self,self.OnBtnGoToLevelUpClick))
end

function OverseaManegeMenuRecommendPopupCell:Start()
end

function OverseaManegeMenuRecommendPopupCell:RefreshShow(data,isMatch)
    if isNull(data) then return end
    self.data = data
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.recipeId)
    if not isNull(vo) then
        CfUtils.FillImage(self.ImgIcon.gameObject,vo.photoPath)
        CfUtils.FillText(self.TextName,vo.name)
    end
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeDojo = component:GetRecipeDoJoById(data.recipeId)
    local isCafeMax = component:IsToMaxCafeLevel()
    local skillId = isCafeMax and self.data.skill2 or self.data.skill1
    self.skillId = skillId
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeRecipeSkillVo(skillId)
    local rating = 1
    if recipeDojo then
        KTool.SetActive(self.LockStatus.gameObject,false)
        KTool.SetActive(self.UnlockStatus.gameObject,true)
        local status = isMatch and 2 or 1
        CfUtils.SetUISwitchImage(self.ImgBg,status)
        CfUtils.SetUISwitchText(self.AddDesc,status)
        CfUtils.SetUISwitchImage(self.ImgFrame1,status)
        CfUtils.SetUISwitchImage(self.ImgFrame2,status)
        rating = recipeDojo.rating
        local makeVo = MaidCoffeeUtils.GetMaidCoffeeMenuMakeVo(data.recipeId)
        if makeVo then
            KTool.SetActive(self.BtnGoToGet,rating ~= #makeVo.experience)
        end
    else
        KTool.SetActive(self.LockStatus.gameObject,true)
        KTool.SetActive(self.UnlockStatus.gameObject,false)
        CfUtils.SetUISwitchImage(self.ImgFrame1,1)
        CfUtils.SetUISwitchImage(self.ImgFrame2,1)
        KTool.SetActive(self.BtnGoToGet,false)
    end
    local addNum = string.split(skillVo.skillNum[rating],",")
    local desc = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr1, addNum,nil,skillVo.percentage)
    CfUtils.FillText(self.TextDesc,desc)
end

function OverseaManegeMenuRecommendPopupCell:SetCallBackAndIndex(callBack,index)

end

function OverseaManegeMenuRecommendPopupCell:OnBtnExplainClick()
    if not isNull(self.skillId) then
        GameUtils.ShowCommonRecipeTips(self.BtnExplain.gameObject,self.skillId)
    end
end

function OverseaManegeMenuRecommendPopupCell:OnBtnGoToLevelUpClick()
    local data = MaidCoffeeUtils.GetMaidCoffeeMenuMakeVo(self.data.recipeId)
    if not isNull(data) then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.foodId)
        if not isNull(goodsVo) then
            local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(goodsVo.jumpAway[1])
            GoodsConfMgr:GetInstance():ExecuteJump(row, {},nil,nil,{goodsVo.jumpParameter[1]})
        end
    end
end

function OverseaManegeMenuRecommendPopupCell:OnBtnGoToGetClick()
    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.recipeId)
    if not isNull(foodVo) then
        if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            if isSet(foodVo,"jumpParameter") then
                local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                if type == Constants.IDType.QuestRegion then
                    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                    local isUnLock,str  =  ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                    if isUnLock then
                        local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                        goodsConfMgr:ExecuteJump(row, {},nil,nil,{foodVo.jumpParameter[1]})
                    else
                        GameUtils.Toast(str)
                    end
                else
                    local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                    goodsConfMgr:ExecuteJump(row, {})
                end
            else
                local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                local recipeVo = CfUtils.GetCfVo(AutoIds.IdSetting3036, "MaidCoffeeMenuMakeVo", self.data.recipeId)
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(recipeVo.fishId)
                if goodsVo then
                    goodsConfMgr:ExecuteJump(row, goodsVo)
                else
                    goodsConfMgr:ExecuteJump(row, {})
                end
            end
        else
            printError("id %s  不能前往跳转 没有配置openType",foodVo.id)
        end
    end
end

function OverseaManegeMenuRecommendPopupCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManegeMenuRecommendPopupCell